            // ALL trailing newlines; the raw exec keeps them.
            threadSummary = unwrap(io.exec(
                'bash ' + shellQuote(ctx.verdictSh) + ' threads ' + shellQuote(threadsPath)))
                .replace(/\n+$/, '');
