// ── one handler per verdict outcome ─────────────────────────────────────────

function applyEscalatedVerdict(opts, io, ctx) {
    var contract = ctx.contract;
    stripRoundLabels(io, ctx);
    ensureLabel(io, ctx, 'needs-human', 'B60205');
    addLabel(io, ctx, 'needs-human');
    var threadSummary = '';
