        '          or (.headRefName | test("^' + number + '[-_.]"))\n' +
        '          or (.headRefName | test("(^|[-_./])gh-0*' + number + '$")))\n' +
        "        | .number] | first // empty'")).trim();

    var prCommentsPath = io.tempFile('pr_comments.json');
    var issueCommentsPath = io.tempFile('issue_comments.json');
